 const COPY_BY_TEXT=new Map(COPY.map(([key,value])=>[value,key])),COPY_BY_KEY=Object.freeze(Object.fromEntries(COPY.map(([key,value])=>[key,value])));
 function interpolate(value,vars){return vars?String(value).replace(/\{(\w+)\}/g,(m,k)=>vars[k]??m):String(value);}
 function translated(key,fallback,vars){const value=typeof g.tr==='function'?g.tr(key,vars):key;return value&&value!==key?value:interpolate(fallback,vars);}
 function localizeHtml(html){let protectedTag=false;return String(html).split(/(<[^>]*>)/g).map((chunk,i)=>{if(!chunk)return '';if(i%2){if(/^<(b|strong|pre|code)\b/i.test(chunk))protectedTag=true;if(/^<\/(b|strong|pre|code)>/i.test(chunk))protectedTag=false;return chunk.replace(/(aria-label=")([^"]+)(")/g,(m,a,value,z)=>{const key=COPY_BY_TEXT.get(value);return key?a+esc(translated(key,COPY_BY_KEY[key]||value))+z:m;});}if(protectedTag)return chunk;const trimmed=chunk.trim(),key=COPY_BY_TEXT.get(trimmed);if(key)return chunk.replace(trimmed,esc(translated(key,COPY_BY_KEY[key]||trimmed)));return chunk.replace(/^Step (\d+) of 6 · (.+)$/,(m,done,label)=>esc(translated(N_('provider.panels.coach_step'),'Step {done} of 6 · {label}',{done,label}))).replace(/^(\d+) engineers · (\d+) support staff$/,(m,engineers,support)=>esc(translated(N_('provider.panels.staff_summary'),'{engineers} engineers · {support} support staff',{engineers,support})));}).join('');}
 function existing(marker,fallback,vars){const value=typeof g.tr==='function'?g.tr(marker,vars):marker;return value&&value!==marker?value:interpolate(fallback,vars);}

 function policyContext(model,policy){
  const project=model?.projects?.find(p=>p.id===policy?.projectId),regionalProvisioning=project?.operationId==='regional-provisioning',integrationAssurance=project?.operationId==='integration-assurance',receipt=project?.operationReceipt;
  const legacy=model?.progression?.claims?.receipts?.find(r=>r.sourceId==='progress.progression-level.2');
  const eligibleMarkets=integrationAssurance?[...(receipt?.binding?.markets||[])]:regionalProvisioning?[...(receipt?.allowedMarkets||legacy?.sourceEvidence?.markets||[])]:[];
  const sourceId=integrationAssurance?receipt?.binding?.sourceId:regionalProvisioning?(receipt?.sourceId||legacy?.sourceId):undefined;
  const boundIds=new Set(receipt?.binding?.customerIds||[]);
  return {regionalProvisioning,integrationAssurance,sourceId,eligibleMarkets,eligibleCustomers:(model?.customers||[]).filter(c=>!['exited','default'].includes(c.status)&&(!regionalProvisioning||eligibleMarkets.includes(c.market))&&(!integrationAssurance||(boundIds.has(c.id)&&eligibleMarkets.includes(c.market)))).map(c=>({id:c.id,name:c.name,market:c.market}))};
 }
